<?php
require '../config/app.php'; require_role(['admin','staff']); $title='Patient Records'; $basePath='../';
$rows=$pdo->query("SELECT u.id,u.name,u.email,u.phone,u.created_at,COUNT(a.id) appointments,COUNT(DISTINCT CASE WHEN a.status='Completed' THEN a.id END) completed FROM users u LEFT JOIN appointments a ON a.patient_id=u.id WHERE u.role='patient' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();
require '../partials/header.php'; ?>
<div class="card p-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><span class="text-primary fw-semibold">PATIENT RECORDS</span><h3 class="mt-1">Patient details & test history</h3></div><input id="patientSearch" class="form-control" style="max-width:260px" placeholder="Search patient..."></div><div class="table-responsive"><table class="table align-middle" id="patientTable"><thead><tr><th>Patient</th><th>Contact</th><th>Appointments</th><th>Completed</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="d-flex align-items-center gap-2"><div class="avatar"><?=strtoupper(substr($r['name'],0,1))?></div><div><strong><?=e($r['name'])?></strong><div class="small text-muted">Joined <?=e(date('d M Y',strtotime($r['created_at'])))?></div></div></div></td><td><?=e($r['email'])?><br><small class="text-muted"><?=e($r['phone']?:'No phone')?></small></td><td><?=e($r['appointments'])?></td><td><?=e($r['completed'])?></td><td><a class="btn btn-sm btn-primary" href="patient_details.php?id=<?=$r['id']?>">View record</a></td></tr><?php endforeach;?></tbody></table></div></div>
<script>document.getElementById('patientSearch').addEventListener('input',function(){let q=this.value.toLowerCase();document.querySelectorAll('#patientTable tbody tr').forEach(r=>r.classList.toggle('d-none',!r.innerText.toLowerCase().includes(q)))});</script>
<?php require '../partials/footer.php'; ?>
